graph_builder_source:
(function buildInput(c,simulations,suffix=""){
 const id=c.id+suffix,root_state=id+":root",choices=c.native_input.choices;
 const states=[{id:root_state,goal:c.native_input.goal,observation:c.native_input.observation.replace(c.id,id),tools:choices.map(x=>({name:x.name,description:"Simulated three-step rewards "+JSON.stringify(x.step_rewards),category:"general",risk:"low"})),value:0}],transitions=[];
 for(const x of choices)for(let step=1;step<=3;step++){
  const nodeId=id+":"+x.name+":"+step;
  states.push({id:nodeId,goal:"Continue the numeric simulation only.",tools:step<3?[{name:x.name+"_step_"+(step+1),description:"Advance to the next numeric reward",category:"general",risk:"low"}]:[],value:0});
  transitions.push({from_state:step===1?root_state:id+":"+x.name+":"+(step-1),tool:step===1?x.name:x.name+"_step_"+step,to_state:nodeId,reward:x.step_rewards[step-1],terminal:step===3});
 }
 return {root_state,states,transitions,simulations,max_depth:3,use_jev_prior:true};
})

search_helper_source:
(async function search(input){
 const started=Date.now();let raw=null,error=null;
 try{raw=await tools.mcp__harness_router__route_mcts(input);}catch(e){error=String(e);}
 const ended=Date.now();let decision=raw?.structuredContent??null;
 if(!decision)for(const part of raw?.content??[])if(part.type==="text"){try{decision=JSON.parse(part.text);break;}catch{}}
 return {started_at_ms:started,ended_at_ms:ended,elapsed_ms:ended-started,decision,error,raw};
})

recording_helper_source:
(async function submit(choice,received){
 const records=load("mcts_rebench_records"),cases=load("mcts_rebench_cases"),search=eval(load("mcts_budget_search"));
 const active=load("mcts_rebench_active");
 if(active){
  if(typeof choice!=="string"||!active.case.native_input.choices.some(c=>c.name===choice))throw Error("Invalid choice");
  const native={started_at_ms:active.started,ended_at_ms:received,elapsed_ms:received-active.started,tool:choice};
  store("mcts_rebench_active",null);
  const mcts=active.mcts??await search(active.case.input);
  records.push({...active.case,native,mcts});store("mcts_rebench_records",records);store("mcts_rebench_index",records.length);
  if(records.length%4===0){text({block_complete:records.length,total:cases.length,errors:records.filter(r=>r.mcts.error||r.mcts.raw?.isError).length});return;}
 }else if(choice!==null){throw Error("No active trial");}
 const index=load("mcts_rebench_index");
 if(index>=cases.length){text({complete:true,trials:records.length});return;}
 const c=cases[index],mcts=c.order==="mcts_first"?await search(c.input):null;
 const started=Date.now();store("mcts_rebench_active",{case:c,mcts,started});
 text({trial:c.trial,total:cases.length,instruction:"Select one root action maximizing the stated discounted reward. Submit its name only; do not execute it or use another tool to calculate the choice.",...c.native_input});
})
